package com.bombay.restaurantintelligence.web;
import com.bombay.restaurantintelligence.normalization.DuplicateSourceException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.Map;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(DuplicateSourceException.class)ResponseEntity<Map<String,Object>> duplicate(DuplicateSourceException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("timestamp",Instant.now().toString(),"error","DUPLICATE_SOURCE","message",e.getMessage()));}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class})ResponseEntity<Map<String,Object>> bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now().toString(),"error","BAD_REQUEST","message",e.getMessage()==null?"Invalid request":e.getMessage()));}}
